package com.servicerca.controller;import com.servicerca.dto.common.PageResponse;import com.servicerca.dto.notification.AppNotificationResponse;import com.servicerca.security.SecurityUser;import com.servicerca.service.InAppNotificationService;import org.springframework.http.ResponseEntity;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import java.util.UUID;@RestController @RequestMapping("/api/v1/notifications")public class AppNotificationController{private final InAppNotificationService service;public AppNotificationController(InAppNotificationService s){service=s;}@GetMapping public PageResponse<AppNotificationResponse>list(@AuthenticationPrincipal SecurityUser u,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return service.list(u.user(),page,size);}@PatchMapping("/{id}/read")public ResponseEntity<AppNotificationResponse>read(@AuthenticationPrincipal SecurityUser u,@PathVariable UUID id){return ResponseEntity.ok(service.read(u.user(),id));}}
